/* BLOCK — full width, stacks vertically, respects width/height/margin */
div, p, h1, section, article { display: block; }  /* defaults */

/* INLINE — sits in text flow, width/height have NO effect */
span, a, strong, em { display: inline; }          /* defaults */

/* INLINE-BLOCK — sits in text flow BUT respects width, height, padding */
.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 999px;
  background: #4fd1c5;
  color: #0e1116;
  font-size: 0.75rem;
  font-weight: 700;
}

/* Removed from layout AND invisible */
.hidden { display: none; }

/* Invisible but STILL takes up space */
.invisible { visibility: hidden; }

/* Transparent but still interactive */
.transparent { opacity: 0; }

/* Visually hidden but accessible to screen readers */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.box {
  overflow: visible; /* default — content spills outside the box */
  overflow: hidden;  /* clips content to the box boundaries */
  overflow: scroll;  /* always shows scrollbars */
  overflow: auto;    /* scrollbars only when content overflows */

  /* Axis-specific */
  overflow-x: hidden;
  overflow-y: auto;
}
